function tab(id){if(id!=='play'&&active&&!paused){paused=true;$('pause').textContent='▶'}document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==id));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));if(id==='collection')collection();updateUI()}
