function gain(xp,coins){save.coins+=coins;const id=save.selected;save.xp[id]=(save.xp[id]||0)+xp;while(save.xp[id]>=level()*100){save.xp[id]-=level()*100;save.levels[id]=level()+1;player.max=maxhp();player.hp=player.max;toast(species[id].name+' reached level '+level()+'!');burst(player.x,player.y,'#e5ff9d',30);tone(880)}persist()}
