window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)&&active)e.preventDefault();keys[e.key.toLowerCase()]=true;keys[e.key]=true;if(e.key.toLowerCase()==='e'&&!e.repeat)capture();if(e.key==='Shift'&&!e.repeat)dash();if(e.key==='Escape')$('pause').click()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;keys[e.key]=false});window.addEventListener('blur',()=>{keys={};if(active&&!paused)$('pause').click()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&active&&!paused)$('pause').click()});
